import 'dart:math' as math;

import '../../engine/dsp/analysis.dart';
import '../../engine/util/expr.dart';
import '../../engine/video/model.dart';

/// Camera state of one clip at a local time – mirrors exactly the zoompan /
/// rotate expressions generated by `VideoCompiler._motion`.
class CamState {
  final double zoom, px, py, rotationDeg;
  const CamState(this.zoom, this.px, this.py, this.rotationDeg);
}

CamState cameraAt(VisualClip c, double t, double dur, {required double clipStart, AudioAnalysis? music, double musicOffset = 0}) {
  final staticMotion = c.motion.isStatic && c.animIn != 'zoom' && c.animIn != 'pop' && c.animIn != 'spin';
  if (staticMotion) return const CamState(1, 0.5, 0.5, 0);
  final m = resolveMotion(c.motion, dur);
  double z, px = 0.5, py = 0.5;
  if (m.preset == MotionPreset.shake) {
    final a = 0.012 + 0.03 * m.intensity;
    z = 1.12;
    px = 0.5 + a * math.sin(t * 23) + a * 0.6 * math.sin(t * 37);
    py = 0.5 + a * math.cos(t * 19) + a * 0.5 * math.sin(t * 29);
  } else if (m.preset == MotionPreset.beatPulse) {
    var period = 0.5, phase = 0.0;
    if (music != null && music.beats.length > 2) {
      period = 60 / music.bpm;
      phase = music.beats.first + musicOffset;
    }
    final abs = t + clipStart;
    z = 1.06 * (1 + (0.04 + 0.1 * m.intensity) * math.exp(-9 * (math.max(abs - phase, 0) % period)));
  } else {
    z = m.zoom.isEmpty ? 1 : evalKeyframes(m.zoom, t);
    if (m.panX.isNotEmpty) px = evalKeyframes(m.panX, t);
    if (m.panY.isNotEmpty) py = evalKeyframes(m.panY, t);
  }
  if (c.animIn == 'zoom' || c.animIn == 'pop') {
    final d = math.max(0.05, c.animInDur);
    final from = c.animIn == 'zoom' ? 1.6 : 1.25;
    if (t < d) z *= from - (from - 1) * t / d;
  }
  var rot = m.rotation.isEmpty ? 0.0 : evalKeyframes(m.rotation, t);
  if (c.animIn == 'spin') {
    final d = math.max(0.05, c.animInDur);
    if (t < d) rot += 360 * (1 - t / d);
  }
  return CamState(math.max(1, z), px.clamp(0, 1).toDouble(), py.clamp(0, 1).toDouble(), rot);
}

/// What is visible at time [t] on the main track.
class TrackState {
  final int index; // current clip
  final double local; // time inside current clip
  final int? next; // incoming clip during a transition
  final double nextLocal;
  final double progress; // 0..1 of the transition
  final String transition;
  const TrackState(this.index, this.local, this.next, this.nextLocal, this.progress, this.transition);
}

TrackState? trackAt(VideoProject p, List<double> starts, double t) {
  if (p.clips.isEmpty) return null;
  var i = 0;
  for (var k = 0; k < p.clips.length; k++) {
    if (t >= starts[k]) i = k;
  }
  // if we're inside the transition region of clip i-1 → i, report i-1 as current
  if (i > 0) {
    final prev = i - 1;
    final td = p.effectiveTransition(prev);
    if (!p.clips[prev].transition.isCut && t < starts[i] + td) {
      return TrackState(prev, t - starts[prev], i, t - starts[i], ((t - starts[i]) / td).clamp(0.0, 1.0), p.clips[prev].transition.type);
    }
  }
  return TrackState(i, (t - starts[i]).clamp(0, p.clips[i].duration).toDouble(), null, 0, 0, 'cut');
}

/// Opacity from fade in/out entrance animations of a clip.
double clipAlpha(VisualClip c, double t, double dur) {
  var a = 1.0;
  if (c.animIn == 'fade') a *= (t / math.max(0.01, math.min(c.animInDur, dur / 2))).clamp(0.0, 1.0);
  if (c.animOut == 'fade') {
    final d = math.min(c.animOutDur, dur / 2);
    a *= ((dur - t) / math.max(0.01, d)).clamp(0.0, 1.0);
  }
  return a;
}

/// Beat envelope (1 at a beat, exponential decay) on the timeline.
double beatEnvelope(AudioAnalysis? a, double t, {double offset = 0, double decay = 8}) {
  if (a == null || a.beats.isEmpty) return 0;
  final bs = a.beats;
  final x = t - offset;
  var lo = 0, hi = bs.length - 1, idx = -1;
  while (lo <= hi) {
    final m = (lo + hi) >> 1;
    if (bs[m] <= x) {
      idx = m;
      lo = m + 1;
    } else {
      hi = m - 1;
    }
  }
  if (idx < 0) return 0;
  return math.exp(-(x - bs[idx]) * decay);
}
